<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Composition with Red, Blue and Yellow — Piet Mondrian, 1930</title>
<meta name="description" content="Composition with Red, Blue and Yellow (1930), oil on canvas by Piet Mondrian. De Stijl. Kunsthaus Zurich.">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@400;500;700&display=swap" rel="stylesheet">
<style>
  :root{
    --black:#111111;
    --white:#fdfcf7;
    --paper:#f6f5ee;
    --red:#e1351b;
    --blue:#0d3fd6;
    --yellow:#ffd21a;
    --grey:#9a9a94;
    --line:8px solid var(--black);
  }
  *{box-sizing:border-box;margin:0;padding:0}
  html{scroll-behavior:smooth}
  body{
    font-family:"Space Grotesk",system-ui,sans-serif;
    color:var(--black);
    background:var(--paper);
    line-height:1.55;
    -webkit-font-smoothing:antialiased;
  }
  a{color:inherit}

  /* ---------- header ---------- */
  header{
    display:flex;justify-content:space-between;align-items:center;gap:1rem;
    padding:1rem 1.5rem;border-bottom:var(--line);background:var(--white);
    position:sticky;top:0;z-index:10;
  }
  header .brand{font-weight:700;letter-spacing:.12em;text-transform:uppercase;font-size:.8rem}
  header .brand b{color:transparent;background:var(--red);-webkit-background-clip:text;background-clip:text}
  header .meta{font-size:.8rem;letter-spacing:.08em;text-transform:uppercase;opacity:.8}

  /* ---------- hero ---------- */
  .hero{
    display:grid;grid-template-columns:1.05fr .95fr;gap:0;
    border-bottom:var(--line);background:var(--white);
    min-height:calc(100vh - 58px);
  }
  .hero-copy{
    padding:clamp(1.5rem,5vw,4rem);display:flex;flex-direction:column;justify-content:center;gap:1.4rem;
  }
  .eyebrow{
    display:inline-flex;align-items:center;gap:.6rem;width:fit-content;
    font-size:.78rem;font-weight:700;letter-spacing:.22em;text-transform:uppercase;
    border:3px solid var(--black);padding:.4rem .8rem;background:var(--yellow);
  }
  h1{
    font-size:clamp(2.4rem,6vw,4.6rem);
    line-height:.98;font-weight:700;letter-spacing:-.02em;text-wrap:balance;
  }
  h1 .thin{font-weight:400}
  .lede{font-size:clamp(1.05rem,1.6vw,1.3rem);max-width:34ch;color:#2c2c2c}
  .lede b{background:var(--yellow);box-shadow:0 0 0 .2em var(--yellow)}
  .facts-row{display:flex;flex-wrap:wrap;gap:.6rem;font-size:.82rem;letter-spacing:.04em;text-transform:uppercase;font-weight:500}
  .facts-row span{border:3px solid var(--black);padding:.35rem .7rem;background:var(--white)}
  .cta{
    align-self:flex-start;display:inline-flex;align-items:center;gap:.6rem;
    font-weight:700;text-decoration:none;text-transform:uppercase;letter-spacing:.1em;font-size:.85rem;
    background:var(--black);color:var(--white);padding:1rem 1.6rem;border:3px solid var(--black);
    transition:transform .15s ease, background .15s ease, color .15s ease;
  }
  .cta:hover{transform:translate(-3px,-3px);box-shadow:6px 6px 0 var(--red)}
  .cta:active{transform:translate(0,0);box-shadow:none}

  .painting{position:relative;border-left:var(--line);background:var(--white);display:flex;align-items:center;justify-content:center;padding:clamp(1rem,4vw,3rem)}
  .painting figure{width:min(100%,460px);border:var(--line);background:var(--white);filter:drop-shadow(10px 10px 0 var(--black))}
  .painting figcaption{
    text-align:center;font-size:.78rem;letter-spacing:.06em;text-transform:uppercase;
    padding:.7rem 1rem;border-top:var(--line);background:var(--white);
  }
  svg.artwork{display:block;width:100%;height:auto}
  svg.artwork .blk{transform-origin:center;transform-box:fill-box}
  .anim-lines line{stroke-dasharray:1000;stroke-dashoffset:1000;animation:draw 1.4s ease forwards}
  .anim-lines li
